+        }
+        text.append("Total: ").append(brl(reservation.price().total())).append('\n');
+        return text.toString();
+    }
+
+    private static String brl(BigDecimal amount) {
+        return "BRL " + String.format(Locale.US, "%,.2f", amount);
+    }
